class Solution {
    fun reachableNodes(edges:Array<IntArray>,maxMoves:Int,n:Int):Int{
        val graph=Array(n){
            mutableListOf<IntArray>()
        };
        for(edge in edges){
            graph[edge[0]].add(intArrayOf(edge[1],edge[2]+1));
            graph[edge[1]].add(intArrayOf(edge[0],edge[2]+1))
        };
        val distance=LongArray(n){
            Long.MAX_VALUE
        };
        distance[0]=0;
        val heap=java.util.PriorityQueue<LongArray>(compareBy{
            it[0]
        });
        heap.add(longArrayOf(0,0));
        while(heap.isNotEmpty()){
            val state=heap.remove();
            val node=state[1].toInt();
            if(state[0]!=distance[node])continue;
            for(edge in graph[node]){
                val next=state[0]+edge[1];
                if(next<distance[edge[0]]){
                    distance[edge[0]]=next;
                    heap.add(longArrayOf(next,edge[0].toLong()))
                }
            }
        };
        var answer=distance.count{
            it<=maxMoves
        }.toLong();
        for(edge in edges){
            val fromU=if(distance[edge[0]]<=maxMoves)maxMoves-distance[edge[0]] else 0;
            val fromV=if(distance[edge[1]]<=maxMoves)maxMoves-distance[edge[1]] else 0;
            answer+=minOf(edge[2].toLong(),fromU+fromV)
        };
        return answer.toInt()
    }
}

